        divider = grid[sep_row][0]
    else:
        sep_col = next(c for c in range(w)
                       if all(grid[r][c] == grid[0][c] for r in range(h)))
        first = [row[:sep_col] for row in grid]
        second = [row[sep_col + 1:] for row in grid]
        divider = grid[0][sep_col]

    # Each panel has a common background and sparse marked cells.
    def background(panel):
        counts = {}
        for row in panel:
            for x in row:
                if x != divider:
                    counts[x] = counts.get(x, 0) + 1
        return max(counts, key=counts.get)

    bg1, bg2 = background(first), background(second)
    out = []
    for r in range(len(first)):
        row = []
        for c in range(len(first[r])):
            marked1 = first[r][c] != bg1
            marked2 = second[r][c] != bg2
            row.append(3 if marked1 and marked2 else bg1)
        out.append(row)
